-- Original lesson drafts only; never publish or create reviewer approval.
do $seed$
declare actor uuid; lesson jsonb;
begin
 select au.user_id into actor from admin.admin_users au join admin.roles r on r.id=au.role_id where au.active and r.key='super_admin' order by au.created_at limit 1;
 if actor is null then raise exception 'Active content owner required'; end if;
 for lesson in select value from jsonb_array_elements($content$[{"program_key": "tvet_foundation_math", "title": "Unit prices and a materials budget", "estimated_minutes": 35, "learning_objectives": ["Calculate a unit price in Birr.", "Compare offers with equal quantities and include stated transport costs.", "Check whether a materials plan fits a fixed budget."], "lesson_explanation": "A unit price tells us the cost of one item or one standard unit. Divide the total price by the number of units. Keep the unit beside the number: Birr per notebook is different from Birr per pack. To find a total cost, multiply the unit price by the quantity. Add any explicitly stated costs, such as transport. Do not assume that the lowest pack price is the cheapest offer: a smaller pack can cost less in total but more per item.\n\nSuppose a training group needs 12 notebooks. In this fictional exercise, shop A offers a pack of 4 for 80 Birr; shop B offers a pack of 6 for 126 Birr. A costs 80 ÷ 4 = 20 Birr per notebook. B costs 126 ÷ 6 = 21 Birr per notebook. Both pack sizes divide exactly into 12. Three packs from A cost 240 Birr; two packs from B cost 252 Birr. If transport from A costs 20 Birr and collection from B costs nothing, the delivered totals are 260 Birr and 252 Birr. B is cheaper for this particular purchase, even though its unit price before transport is higher.\n\nA budget is a spending limit or plan. With a 300 Birr limit, buying from B leaves 300 − 252 = 48 Birr. Check by adding the cost and remainder: 252 + 48 = 300. An estimate provides another check: 12 notebooks at about 20 Birr each should cost about 240 Birr before extra costs. A result of 2,400 Birr would be a warning to check multiplication or units.\n\nRecord quantity, unit, unit price, extra costs and total in separate columns. Compare items of suitable quality; this arithmetic does not prove that products are equally durable. All prices here are invented for learning and are not current Ethiopian shop quotations.", "ethiopian_context_examples": ["A TVET group plans a notebook purchase in Birr using two fictional shop offers. Learners can replace these with teacher-provided quotations without sharing private household finances."], "worked_practice": [{"question": "A pack of 5 exercise books costs 150 Birr. What is the unit price?", "answer": "30 Birr per book", "explanation": "150 Birr divided by 5 books equals 30 Birr per book."}, {"question": "You need 15 books at that price and pay 25 Birr transport. Find the total and the remainder from 500 Birr.", "answer": "475 Birr total; 25 Birr remaining", "explanation": "15 × 30 = 450; 450 + 25 = 475; 500 − 475 = 25."}, {"question": "Offer X sells 10 pencils for 40 Birr. Offer Y sells 8 for 36 Birr. Which has the lower unit price?", "answer": "X: 4 Birr per pencil, compared with 4.5 Birr for Y.", "explanation": "40 ÷ 10 = 4 and 36 ÷ 8 = 4.5. Compare equal units, not just pack totals."}], "independent_task": "Prepare a four-line fictional materials budget for a class activity. State quantities, units and prices in Birr, include a transport cost and check that the sum fits a limit you choose. Explain one limitation of a price-only comparison.", "assessment_rubric": ["Unit prices include correct units.", "Multiplication and extra costs are correct.", "Total plus remainder equals the budget.", "Comparison states quality or transport assumptions."], "schema_version": 1, "language_code": "en", "status": "draft", "review_status": "needs_qualified_review", "source_status": "original_draft_needs_curriculum_alignment", "source_attribution": [{"type": "original", "note": "Original AI-assisted teaching draft; not copied from or certified against an official textbook."}], "accessibility_text_alternatives": ["All information is in selectable text. No image, colour or audio is needed to complete the activity."], "translation_workflow": {"am": "not_started", "om": "not_started", "ti": "not_started", "so": "not_started"}, "translation_notes": "Keep Birr units and quantities consistent. Ask native-language reviewers to check terminology, natural phrasing and equivalence of answers. Do not mark a translation approved automatically.", "publication_blocked_reason": "Qualified subject, language and accessibility review required; official curriculum alignment unverified."}, {"program_key": "tvet_foundation_communication", "title": "A clear workplace request and confirmation", "estimated_minutes": 30, "learning_objectives": ["Identify audience, purpose and required action in a workplace message.", "Write a specific, respectful request.", "Confirm an instruction without assuming missing details."], "lesson_explanation": "A useful workplace message helps its reader act. Before writing, identify who needs the message, what they need to know and what response you need. Include enough detail to prevent confusion, but leave out unrelated personal information. A short request often has five parts: a subject, a respectful greeting, the situation, a specific request and a closing.\n\nCompare these two fictional training messages. “Bring the things soon” leaves the recipient guessing about the items and time. “Hello Hana, for our supervised workshop practice on Tuesday, please bring two blank job sheets to Room 2 by 9:00 a.m. Please confirm whether they are available. Thank you, Meron” identifies the activity, items, place, deadline and response. In real work, include the date when “Tuesday” could be ambiguous. Use the calendar and time convention agreed by your workplace; do not assume that everyone means the same time from an unqualified number.\n\nA request should be polite without hiding the action. “Could you confirm the delivery date by tomorrow afternoon?” is clearer than “Please do the necessary.” If you cannot meet a request, state the problem early and offer a realistic alternative: “I can prepare one sheet today and the second tomorrow morning. Would that work?” Do not promise a deadline you cannot meet.\n\nWhen receiving an instruction, listen or read completely. Repeat the essential action and ask about missing information: “To confirm, I should prepare two blank sheets for Room 2. Which date and time should I use?” Confirmation is especially important when quantities, dates, locations or responsibilities are unclear. For hazardous work, stop and ask the authorised supervisor rather than guessing; this lesson does not qualify anyone to perform technical tasks.\n\nBefore sending a message, check names, quantities, attachments and recipient. Use the approved class or workplace channel. Practise with fictional details instead of sharing your phone number, identification documents, passwords or a real customer's data. A message is complete when the reader understands the next step, not merely when the writer has sent it.", "ethiopian_context_examples": ["A fictional TVET workshop group uses an agreed calendar and time convention to arrange supervised practice. Learners may discuss the message in their strongest language before drafting in English."], "worked_practice": [{"question": "What is missing from “Please bring the tools tomorrow”?", "answer": "Which tools, how many, where, what date/time and whether confirmation is needed.", "explanation": "The recipient cannot reliably carry out the request without these details. Do not invent them; ask."}, {"question": "Rewrite “I cannot do it” as a constructive response when you can complete the task on Friday.", "answer": "I cannot complete the task by Thursday. I can finish it on Friday. Would that meet your needs?", "explanation": "The response states the limit and a specific alternative without promising the original deadline."}, {"question": "An instruction uses a time convention you do not understand. What should you do?", "answer": "Ask the sender to confirm the exact time and agreed convention.", "explanation": "Repeating an unclear time does not resolve the ambiguity. Confirmation prevents a missed appointment."}], "independent_task": "Write a 60–90 word fictional request for class materials. Include audience, purpose, quantity, place, a clearly stated date/time and a request for confirmation. Swap with a partner and mark any detail that requires a guess.", "assessment_rubric": ["Purpose and requested action are explicit.", "Quantities, place and date/time are unambiguous.", "Tone is respectful and concise.", "No private personal data is included.", "Recipient can reply with a clear next step."], "schema_version": 1, "language_code": "en", "status": "draft", "review_status": "needs_qualified_review", "source_status": "original_draft_needs_curriculum_alignment", "source_attribution": [{"type": "original", "note": "Original AI-assisted teaching draft; not copied from or certified against an official textbook."}], "accessibility_text_alternatives": ["All information is in selectable text. No image, colour or audio is needed to complete the activity."], "translation_workflow": {"am": "not_started", "om": "not_started", "ti": "not_started", "so": "not_started"}, "translation_notes": "Keep Birr units and quantities consistent. Ask native-language reviewers to check terminology, natural phrasing and equivalence of answers. Do not mark a translation approved automatically.", "publication_blocked_reason": "Qualified subject, language and accessibility review required; official curriculum alignment unverified."}]$content$::jsonb) loop
  if not exists(select 1 from admin.content_drafts where program_key=lesson->>'program_key' and title=lesson->>'title' and status<>'archived') then
   insert into admin.content_drafts(entity_type,program_key,language_code,title,payload,status,created_by,updated_by)
   values('chapter',lesson->>'program_key','en',lesson->>'title',lesson,'draft',actor,actor);
  end if;
 end loop;
end $seed$;
